def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (2, 8):
                height = 5 if value == 2 else 4
                top = max(0, r - height + 1)
                for rr in range(top, r):
                    out[rr][c] = 1
                out[top][c] = value
    return out
